  rcwrite('INSERT INTO neptune_tba_schedule_settings(id,live_interval_minutes,weekly_enabled,weekly_day,weekly_hour,weekly_minute,updated_by) VALUES(1,?,?,?,?,?,NULL) ON DUPLICATE KEY UPDATE live_interval_minutes=VALUES(live_interval_minutes),weekly_enabled=VALUES(weekly_enabled),weekly_day=VALUES(weekly_day),weekly_hour=VALUES(weekly_hour),weekly_minute=VALUES(weekly_minute),updated_at=CURRENT_TIMESTAMP',[$interval,$enabled,$day,$hour,$minute]);rcaudit($platform,'rc_augur_schedule_saved');$out=['message'=>'Schedules saved'];
